async function load(id){const[o,m,q,c]=await Promise.all([db().from("golf_outings").select("*").eq("id",id).maybeSingle(),loadMembers(),db().from("golf_quick_rounds").select("*").eq("outing_id",id).maybeSingle(),db().from("golf_courses").select("id,name,city,state,holes").order("name")]);if(o.error||!o.data)throw o.error||new Error("Event not found");return{outing:o.data,members:m||[],round:q.data||null,courses:c.error?[]:(c.data||[])};}
async function ensureRound(d){if(d.round)return d.round;if(!d.outing.course_id)throw new Error("Choose a saved course for this Quick Round event first.");const {data,error}=await db().from("golf_quick_rounds").insert({outing_id:d.outing.id,course_id:d.outing.course_id,created_by:Number(getMemberId()),played_on:d.outing.event_date||new Date().toISOString().slice(0,10),holes:Number(d.outing.holes)||18,status:d.outing.status==="final"?"final":"active"}).select().single();if(error)throw error;d.round=data;return data;}
function quickEventSetup(d){const options=d.courses.map(c=>`<option value="${c.id}" data-name="${esc(c.name)}" data-holes="${Number(c.holes)||18}">${esc(c.name)}${c.city||c.state?` · ${esc([c.city,c.state].filter(Boolean).join(", "))}`:""}</option>`).join("");return `<section class="card" data-gqm-root data-gqm-event-setup><div class="card-title-row"><div><div class="card-title">Quick Round setup</div><p class="muted tiny">Choose the course and round length before adding golfers.</p></div><span class="pill">Quick Round</span></div><div class="card-body gqm">${canEdit("golf_outings")?`<label>Course<select data-gqm-setup-course><option value="">Choose a saved course…</option>${options}</select></label><label>Round length<select data-gqm-setup-holes><option value="18">18 holes</option><option value="9">9 holes</option></select></label><button type="button" class="btn primary" data-gqm-save-setup ${options?"":"disabled"}>Save & continue</button>${options?"":`<p class="muted tiny">Add a saved course in Golf setup first.</p>`}`:`<p class="muted">This Quick Round is waiting for a commissioner to choose its course.</p>`}</div></section>`;}
function wireQuickEventSetup(root,d){root.querySelector("[data-gqm-save-setup]")?.addEventListener("click",async e=>{const course=root.querySelector("[data-gqm-setup-course]"),holes=root.querySelector("[data-gqm-setup-holes]"),selected=course?.selectedOptions?.[0];if(!course?.value)return toast("Choose a saved course",true);e.currentTarget.disabled=true;const patch={course_id:Number(course.value),course:selected?.dataset.name||selected?.textContent||"",holes:Number(holes?.value)||Number(selected?.dataset.holes)||18,status:"setup"};const result=await db().from("golf_outings").update(patch).eq("id",d.outing.id);if(result.error){e.currentTarget.disabled=false;return toast(result.error.message||"Could not save Quick Round setup",true)}toast("Quick Round setup saved");paint()});}
async function paint(){
  const routeState=route();
  if(!routeState.golf||!routeState.id){document.body.classList.remove("gqm-focus");return}
  let d;try{d=await load(Number(routeState.id))}catch{return}
  if(d.outing.event_type!=="quick"){document.body.classList.remove("gqm-focus");return}
  ensureQuickRoundStyles();ensureQuickRoundFocusStyles();ensureQuickRoundDetailStyles();ensureQuickCourseStyles();ensureScorecardStyles();
  const root=document.querySelector("#golf-outing");if(!root)return;
  if(!d.outing.course_id&&!d.round){document.body.classList.remove("gqm-focus");root.innerHTML=quickEventSetup(d);wireQuickEventSetup(root,d);return}
  try{
    const round=await ensureRound(d);
    const playersResult=await db().from("golf_quick_players").select("*").eq("round_id",round.id).order("sort_order");
    if(playersResult.error)throw playersResult.error;
    const players=playersResult.data||[],courseIds=[...new Set([Number(round.course_id),...players.map(player=>Number(player.course_id))].filter(Boolean))];
    const [scoresResult,holesResult]=await Promise.all([
      players.length?db().from("golf_quick_scores").select("*").in("player_id",players.map(player=>player.id)):Promise.resolve({data:[],error:null}),
      db().from("golf_course_holes").select("course_id,hole,par,yardage_men,yardage_women,handicap").in("course_id",courseIds).order("hole")
    ]);
    if(scoresResult.error||holesResult.error)throw scoresResult.error||holesResult.error;
    const scores=scoresResult.data||[],holesByCourse=quickCourseHoleMap(holesResult.data||[]);
    root.innerHTML=quickMarkup(d,round,players,scores,holesByCourse);
    document.body.classList.toggle("gqm-focus",players.length>0);
    wire(root,d,round,players);
    wireModern(root,d,round,players,holesByCourse,scores);
  }catch(error){
    document.body.classList.remove("gqm-focus");
    root.innerHTML=`<section class="card" data-gqm-root><div class="card-title">Quick Round</div><div class="card-body"><p class="muted">${esc(error.message||error)}</p></div></section>`;
  }
}
const playerScores=(scores,id)=>new Map(scores.filter(s=>String(s.player_id)===String(id)).map(s=>[Number(s.hole),s]));
function scoreTotal(map,holes,holeCount){let strokes=0,par=0;for(let h=1;h<=holeCount;h++){const v=Number(map.get(h)?.strokes)||0;if(!v)continue;strokes+=v;par+=holePar(holes,h)}return{strokes,par}}
