    root.querySelector("[data-gqm-add]")?.addEventListener("click",async event=>{const selected=[...root.querySelectorAll("[data-gqm-add-member]:checked")],guest=root.querySelector("[data-gqm-add-guest]")?.value.trim()||"",count=selected.length+(guest?1:0);if(!count)return toast("Choose a member or enter a guest name",true);if(players.length+count>4)return toast(`You can add ${4-players.length} more golfer${4-players.length===1?"":"s"}`,true);event.currentTarget.disabled=true;const rows=[...selected.map((input,index)=>({round_id:r.id,member_id:Number(input.value),course_id:Number(input.closest(".gqm-person-course")?.querySelector("[data-gqm-add-member-course]")?.value)||null,sort_order:players.length+index})),...(guest?[{round_id:r.id,guest_name:guest,course_id:Number(root.querySelector("[data-gqm-add-guest-course]")?.value)||null,sort_order:players.length+selected.length}]:[])],result=await db().from("golf_quick_players").insert(rows);if(result.error){event.currentTarget.disabled=false;return toast(result.error.message||"Could not add golfers",true)}toast(count===1?"Golfer added":"Golfers added");paint()});
